{
  "name": "backoffice-angular",
  "$schema": "../../node_modules/nx/schemas/project-schema.json",
  "projectType": "application",
  "prefix": "app",
  "sourceRoot": "apps/backoffice-angular/src",
  "tags": ["type:app", "scope:app"],
  "i18n": {
    "sourceLocale": "fr"
  },
  "cli": {
    "cache": {
      "enabled": false
    }
  },
  "targets": {
    "build": {
      "executor": "@angular/build:application",
      "outputs": ["{options.outputPath}"],
      "defaultConfiguration": "production",
      "options": {
        "outputPath": "dist/apps/backoffice-angular",
        "browser": "apps/backoffice-angular/src/main.ts",
        "polyfills": ["@angular/localize/init"],
        "tsConfig": "apps/backoffice-angular/tsconfig.app.json",
        "inlineStyleLanguage": "scss",
        "assets": [
          {
            "glob": "**/*",
            "input": "apps/backoffice-angular/public"
          }
        ],
        "styles": [
          "apps/backoffice-angular/src/tailwind.css",
          "apps/backoffice-angular/src/styles.scss",
          "node_modules/ol/ol.css"
        ],
        "allowedCommonJsDependencies": ["exceljs", "ol"]
      },
      "configurations": {
        "production": {
          "budgets": [
            {
              "type": "initial",
              "maximumWarning": "900kb",
              "maximumError": "1mb"
            },
            {
              "type": "anyComponentStyle",
              "maximumWarning": "4kb",
              "maximumError": "8kb"
            }
          ],
          "outputHashing": "all"
        },
        "development": {
          "optimization": false,
          "extractLicenses": false,
          "sourceMap": true
        }
      }
    },
    "serve": {
      "continuous": true,
      "executor": "@angular/build:dev-server",
      "defaultConfiguration": "development",
      "configurations": {
        "production": {
          "buildTarget": "backoffice-angular:build:production"
        },
        "development": {
          "buildTarget": "backoffice-angular:build:development",
          "proxyConfig": "apps/backoffice-angular/proxy.conf.json"
        }
      }
    },
    "lint": {
      "inputs": [
        "default",
        "^default",
        "{workspaceRoot}/.eslintrc.json",
        "{workspaceRoot}/.eslintignore",
        "{workspaceRoot}/eslint.config.mjs",
        {
          "externalDependencies": ["eslint"]
        }
      ]
    },
    "test": {
      "executor": "@angular/build:unit-test",
      "options": {
        "watch": false,
        "runnerConfig": "tools/generator-platform/page-realization-vitest.config.mjs"
      }
    },
    "e2e": {
      "executor": "nx:run-commands",
      "options": {
        "command": "bunx playwright test -c apps/backoffice-angular/playwright.config.mjs",
        "cwd": "{workspaceRoot}"
      }
    },
    "e2e-workspace-memory": {
      "executor": "nx:run-commands",
      "cache": false,
      "options": {
        "command": "bunx playwright test -c apps/backoffice-angular/playwright.memory.config.mjs",
        "cwd": "{workspaceRoot}"
      }
    },
    "serve-static": {
      "continuous": true,
      "executor": "@nx/web:file-server",
      "options": {
        "buildTarget": "backoffice-angular:build",
        "staticFilePath": "dist/apps/backoffice-angular/browser",
        "spa": true
      }
    }
  }
}

